def kruskal_mst(n, edges)
  edges = edges.sort_by { |e| e[2] }
  dsu = DSU.new(n)
  total = 0
  cnt = 0
  edges.each do |u,v,w|
    if dsu.unite(u,v)
      total += w
      cnt += 1
      break if cnt == n-1
    end
  end
  cnt == n-1 ? total : -1
end

