class LRUNode
  attr_accessor :key, :val, :prev, :next
  def initialize(key, val)
    @key, @val = key, val
    @prev = @next = nil
  end
end

class LRUCache
  def initialize(capacity)
    raise ArgumentError, 'capacity must be > 0' if capacity <= 0
    @cap = capacity
    @map = {}
    @head = LRUNode.new(nil, nil)
    @tail = LRUNode.new(nil, nil)
    @head.next = @tail
    @tail.prev = @head
  end

  def add_front(node)
    node.prev = @head
    node.next = @head.next
    @head.next.prev = node
    @head.next = node
  end

  def remove(node)
    node.prev.next = node.next
    node.next.prev = node.prev
    node.prev = node.next = nil
  end

  def move_front(node)
    remove(node)
    add_front(node)
  end

  def pop_tail
    node = @tail.prev
    return nil if node.equal?(@head)
    remove(node)
    node
  end

  def get(key)
    node = @map[key]
    return nil unless node
    move_front(node)
    node.val
  end

  def put(key, value)
    if (node = @map[key])
      node.val = value
      move_front(node)
      return
    end
    node = LRUNode.new(key, value)
    @map[key] = node
    add_front(node)
    if @map.length > @cap
      old = pop_tail
      @map.delete(old.key) if old && !old.key.nil?
    end
  end
end

