class LRUCache
  def initialize(cap)
    @cap = cap; @cache = {}; @order = []
  end
  def get(k)
    return nil unless @cache.key?(k)
    @order.delete(k); @order << k; @cache[k]
  end
  def put(k, v)
    if @cache.key?(k); @order.delete(k); else @cache.delete(@order.shift) if @cache.size >= @cap; end
    @cache[k] = v; @order << k
  end
end

