class SlidingWindowLimiter
  def initialize(max, window)
    @max = max
    @window = window
    @requests = []
    @mutex = Mutex.new
  end
  def allow?
    @mutex.synchronize do
      now = Time.now.to_f
      @requests.reject! { |t| now - t > @window }
      if @requests.size < @max
        @requests << now
        true
      else
        false
      end
    end
  end
end

class BloomFilter
  def initialize(size)
    @size = size
    @bits = Array.new(size, false)
  end
  def h1(s)
    s.sum % @size
  end
  def h2(s)
    (s.sum * 31) % @size
  end
  def add(item)
    @bits[h1(item.to_s)] = true
    @bits[h2(item.to_s)] = true
  end
  def include?(item)
    @bits[h1(item.to_s)] && @bits[h2(item.to_s)]
  end
end

class RingBuffer
  def initialize(capacity)
    @capacity = capacity
    @buffer = Array.new(capacity)
    @read = 0
    @write = 0
    @mutex = Mutex.new
  end
  def push(item)
    @mutex.synchronize do
      return false if @write - @read >= @capacity
      @buffer[@write % @capacity] = item
      @write += 1
      true
    end
  end
  def pop
    @mutex.synchronize do
      return nil if @write <= @read
      item = @buffer[@read % @capacity]
      @read += 1
      item
    end
  end
end

